<?php
require_once __DIR__.'/config.php';require_role(['admin','hr','viewer']);$id=(int)($_GET['id']??0);$edit=$id>0;$can=in_array($_SESSION['role'],['admin','hr'],true);
$emp=['employee_no'=>'','first_name'=>'','middle_name'=>'','last_name'=>'','suffix'=>'','sex'=>'','birth_date'=>'','email'=>'','phone'=>'','address'=>'','department'=>'','position_title'=>'','employment_status'=>'Permanent','date_hired'=>'','salary'=>'','photo_path'=>null,'document_path'=>null,'notes'=>''];
if($edit){$s=$db->prepare('SELECT * FROM employees WHERE id=?');$s->bind_param('i',$id);$s->execute();$found=$s->get_result()->fetch_assoc();if(!$found){http_response_code(404);exit('Employee not found');}$emp=$found;}elseif(!$can){http_response_code(403);exit('Viewers cannot create records');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!$can){http_response_code(403);exit('Read-only account');}
$fields=['employee_no','first_name','middle_name','last_name','suffix','sex','birth_date','email','phone','address','department','position_title','employment_status','date_hired','salary','notes'];foreach($fields as $f)$emp[$f]=trim((string)($_POST[$f]??''));
if($emp['employee_no']===''||$emp['first_name']===''||$emp['last_name']==='')$error='Employee number, first name, and last name are required.';
elseif($emp['email']!==''&&!filter_var($emp['email'],FILTER_VALIDATE_EMAIL))$error='Invalid email address.';
else{try{$photo=upload_file('photo','photo');$doc=upload_file('document','document');if($photo)$emp['photo_path']=$photo;if($doc)$emp['document_path']=$doc;
if($edit){$s=$db->prepare("UPDATE employees SET employee_no=?,first_name=?,middle_name=?,last_name=?,suffix=?,sex=?,birth_date=NULLIF(?,''),email=?,phone=?,address=?,department=?,position_title=?,employment_status=?,date_hired=NULLIF(?,''),salary=NULLIF(?,''),photo_path=?,document_path=?,notes=? WHERE id=?");$salary=(string)$emp['salary'];$s->bind_param('ssssssssssssssssssi',$emp['employee_no'],$emp['first_name'],$emp['middle_name'],$emp['last_name'],$emp['suffix'],$emp['sex'],$emp['birth_date'],$emp['email'],$emp['phone'],$emp['address'],$emp['department'],$emp['position_title'],$emp['employment_status'],$emp['date_hired'],$salary,$emp['photo_path'],$emp['document_path'],$emp['notes'],$id);$s->execute();audit($db,'EMPLOYEE_UPDATED','employee',(string)$id,'Updated '.$emp['employee_no']);}
else{$uid=(int)$_SESSION['user_id'];$s=$db->prepare("INSERT INTO employees(employee_no,first_name,middle_name,last_name,suffix,sex,birth_date,email,phone,address,department,position_title,employment_status,date_hired,salary,photo_path,document_path,notes,created_by) VALUES(?,?,?,?,?,?,NULLIF(?,''),?,?,?,?,?,?,NULLIF(?,''),NULLIF(?,''),?,?,?,?)");$salary=(string)$emp['salary'];$s->bind_param('ssssssssssssssssssi',$emp['employee_no'],$emp['first_name'],$emp['middle_name'],$emp['last_name'],$emp['suffix'],$emp['sex'],$emp['birth_date'],$emp['email'],$emp['phone'],$emp['address'],$emp['department'],$emp['position_title'],$emp['employment_status'],$emp['date_hired'],$salary,$emp['photo_path'],$emp['document_path'],$emp['notes'],$uid);$s->execute();$id=(int)$db->insert_id;audit($db,'EMPLOYEE_CREATED','employee',(string)$id,'Created '.$emp['employee_no']);}
flash('Employee record saved.');header('Location: employee_form.php?id='.$id);exit;
}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Save failed. Check duplicate employee number and database fields.';}}}
page_header($edit?'Employee record':'Add employee');show_flash();echo '<h1>'.($edit?'Employee record':'Add employee').'</h1>';if($error)echo '<div class="notice error">'.h($error).'</div>';
if(!empty($emp['photo_path']))echo '<div class="card"><img src="'.h($emp['photo_path']).'" alt="Employee photo" style="max-width:140px;max-height:140px"></div>';
echo '<div class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="'.h(csrf_token()).'"><fieldset '.(!$can?'disabled':'').' style="border:0;padding:0"><div class="form-grid">';
$fields=['employee_no'=>'Employee number *','first_name'=>'First name *','middle_name'=>'Middle name','last_name'=>'Last name *','suffix'=>'Suffix','email'=>'Email','phone'=>'Phone','birth_date'=>'Birth date','date_hired'=>'Date hired','department'=>'Department','position_title'=>'Position title','salary'=>'Monthly salary','address'=>'Address','notes'=>'Notes'];
foreach($fields as $k=>$label){$type=in_array($k,['birth_date','date_hired'])?'date':($k==='email'?'email':($k==='salary'?'number':'text'));echo '<div><label>'.h($label).'</label>';if(in_array($k,['address','notes']))echo '<textarea name="'.h($k).'">'.h((string)$emp[$k]).'</textarea>';else echo '<input type="'.h($type).'" name="'.h($k).'" value="'.h((string)$emp[$k]).'" '.(in_array($k,['employee_no','first_name','last_name'])?'required':'').' '.($k==='salary'?'min="0" step="0.01"':'').'></div>';}
echo '<div><label>Sex</label><select name="sex"><option value="">Not specified</option>';foreach(['Male','Female','Other','Prefer not to say'] as $v)echo '<option '.(($emp['sex']??'')===$v?'selected':'').' value="'.h($v).'">'.h($v).'</option>';echo '</select></div><div><label>Employment status</label><select name="employment_status">';foreach(['Permanent','Temporary','Contractual','Casual','Job Order','Contract of Service','Resigned','Retired','Separated'] as $v)echo '<option '.($emp['employment_status']===$v?'selected':'').' value="'.h($v).'">'.h($v).'</option>';echo '</select></div><div><label>Photo (JPG/PNG/WEBP, max 5 MB)</label><input type="file" name="photo" accept=".jpg,.jpeg,.png,.webp"></div><div><label>Document (PDF/JPG/PNG, max 5 MB)</label><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png"></div></div></fieldset><div class="actions no-print"><a class="btn muted-btn" href="employees.php">Back</a>';if($can)echo '<button>Save record</button>';echo '</div></form>';
if(!empty($emp['document_path']))echo '<p>Attached file: '.h(basename($emp['document_path'])).'.</p>';echo '</div>';page_footer();